10	/** @public */
11	export interface TLUiMenuGroupProps<TranslationKey extends string = string> {
12		id: string
13		/**
14		 * The label to display on the item. If it's a string, it will be translated. If it's an object, the keys will be used as the language keys and the values will be translated.
15		 */
16		label?: TranslationKey | { [key: string]: TranslationKey }
17		className?: string
18		children?: ReactNode
19	}
20	
21	/** @public @react */
22	export function TldrawUiMenuGroup({ id, label, className, children }: TLUiMenuGroupProps) {
23		const menu = useTldrawUiMenuContext()
24		const { orientation } = useTldrawUiOrientation()
25		const msg = useTranslation()
26		const dir = useDirection()
27		const labelToUse = unwrapLabel(label, menu.type)
28		const labelStr = labelToUse ? msg(labelToUse as TLUiTranslationKey) : undefined
29	
30		switch (menu.type) {
31			case 'menu': {
32				return (
33					<TldrawUiDropdownMenuGroup
34						className={className}
35						data-testid={`${menu.sourceId}-group.${id}`}
36					>
37						{children}
38					</TldrawUiDropdownMenuGroup>
39				)
40			}
41			case 'context-menu': {
42				return (
43					<div
44						dir={dir}
45						className={classNames('tlui-menu__group', className)}
46						data-testid={`${menu.sourceId}-group.${id}`}
47					>
48						{children}
49					</div>
50				)
51			}
52			case 'keyboard-shortcuts': {
53				// todo: if groups need a label, let's give em a label
54				return (
55					<div className="tlui-shortcuts-dialog__group" data-testid={`${menu.sourceId}-group.${id}`}>
56						<h2 className="tlui-shortcuts-dialog__group__title">{labelStr}</h2>
57						<div className="tlui-shortcuts-dialog__group__content">{children}</div>
58					</div>
59				)
60			}
61			case 'toolbar': {
62				const Layout = orientation === 'horizontal' ? TldrawUiRow : TldrawUiColumn
63				return (
64					<Layout className="tlui-main-toolbar__group" data-testid={`${menu.sourceId}-group.${id}`}>
65						{children}
66					</Layout>
67				)
68			}
69			case 'toolbar-overflow': {
70				return (
71					<TldrawUiGrid
72						className="tlui-main-toolbar__group"
73						data-testid={`${menu.sourceId}-group.${id}`}
74					>
75						{children}
76					</TldrawUiGrid>
77				)
78			}
79			default: {
80				return children
81			}
82		}
83	}
