30	/** @public */
31	export interface TLUiMenuItemProps<
32		TranslationKey extends string = string,
33		IconType extends string = string,
34	> {
35		id: string
36		/**
37		 * The icon to display on the item. Icons are only shown in certain menu types.
38		 */
39		icon?: IconType | TLUiIconJsx
40		/**
41		 * An icon to display to the left of the menu item.
42		 */
43		iconLeft?: IconType | TLUiIconJsx
44		/**
45		 * The keyboard shortcut to display on the item.
46		 */
47		kbd?: string
48		/**
49		 * The label to display on the item. If it's a string, it will be translated. If it's an object, the keys will be used as the language keys and the values will be translated.
50		 */
51		label?: TranslationKey | { [key: string]: TranslationKey }
52		/**
53		 * If the editor is in readonly mode and the item is not marked as readonlyok, it will not be rendered.
54		 */
55		readonlyOk?: boolean
56		/**
57		 * The function to call when the item is clicked.
58		 */
59		onSelect(source: TLUiEventSource): Promise<void> | void
60		/**
61		 * Whether this item should be disabled.
62		 */
63		disabled?: boolean
64		/**
65		 * Prevent the menu from closing when the item is clicked
66		 */
67		noClose?: boolean
68		/**
69		 * Whether to show a spinner on the item.
70		 */
71		spinner?: boolean
72		/**
73		 * Whether the item is selected.
74		 */
75		isSelected?: boolean
76		/**
77		 * The function to call when the item is dragged. If this is provided, the item will be draggable.
78		 */
79		onDragStart?(source: TLUiEventSource, info: TLPointerEventInfo): void
80	}
