294	function useDraggableEvents(
295		onDragStart: TLUiToolItem['onDragStart'],
296		onSelect: TLUiToolItem['onSelect']
297	) {
298		const editor = useEditor()
299		const events = useMemo(() => {
300			let state = { name: 'idle' } as
301				| {
302						name: 'idle'
303				  }
304				| {
305						name: 'pointing'
306						screenSpaceStart: VecModel
307				  }
308				| {
309						name: 'dragging'
310						screenSpaceStart: VecModel
311				  }
312				| {
313						name: 'dragged'
314				  }
315	
316			function handlePointerDown(e: React.PointerEvent<HTMLButtonElement>) {
317				state = {
318					name: 'pointing',
319					screenSpaceStart: { x: e.clientX, y: e.clientY },
320				}
321	
322				e.currentTarget.setPointerCapture(e.pointerId)
323			}
324	
325			function handlePointerMove(e: React.PointerEvent<HTMLButtonElement>) {
326				if ((e as any).isSpecialRedispatchedEvent) return
327	
328				if (state.name === 'pointing') {
329					const distanceSq = Vec.Dist2(state.screenSpaceStart, { x: e.clientX, y: e.clientY })
330					if (
331						distanceSq >
332						(editor.getInstanceState().isCoarsePointer
333							? editor.options.uiCoarseDragDistanceSquared
334							: editor.options.uiDragDistanceSquared)
335					) {
336						const screenSpaceStart = state.screenSpaceStart
337						state = {
338							name: 'dragging',
339							screenSpaceStart,
340						}
341	
342						editor.run(() => {
343							editor.setCurrentTool('select')
344	
345							// Set origin point
346							editor.dispatch({
347								type: 'pointer',
348								target: 'canvas',
349								name: 'pointer_down',
350								...getPointerInfo(editor, e),
351								point: screenSpaceStart,
352							})
353	
354							// Pointer down potentially selects shapes, so we need to deselect them.
355							editor.selectNone()
356	
357							// start drag
358							onDragStart?.('toolbar', {
359								type: 'pointer',
360								target: 'canvas',
361								name: 'pointer_move',
362								...getPointerInfo(editor, e),
363								point: screenSpaceStart,
364							})
365	
366							hideAllTooltips()
367							editor.getContainer().focus()
368						})
369					}
370				}
371			}
372	
373			function handlePointerUp(e: React.PointerEvent<HTMLButtonElement>) {
374				if ((e as any).isSpecialRedispatchedEvent) return
375	
376				e.currentTarget.releasePointerCapture(e.pointerId)
377	
378				editor.dispatch({
379					type: 'pointer',
380					target: 'canvas',
381					name: 'pointer_up',
382					...getPointerInfo(editor, e),
383				})
384			}
385	
386			function handleClick() {
387				if (state.name === 'dragging' || state.name === 'dragged') {
388					state = { name: 'idle' }
389					return true
390				}
391	
392				state = { name: 'idle' }
393				onSelect?.('toolbar')
394				return false
395			}
396	
397			return {
398				onPointerDown: handlePointerDown,
399				onPointerMove: handlePointerMove,
400				onPointerUp: handlePointerUp,
401				onClick: handleClick,
402			}
403		}, [onDragStart, editor, onSelect])
404	
405		return events
406	}
