408	function DraggableToolbarButton({
409		id,
410		labelStr,
411		titleStr,
412		disabled,
413		isSelected,
414		icon,
415		onSelect,
416		onDragStart,
417		overflow,
418	}: {
419		id: string
420		disabled: boolean
421		labelStr?: string
422		titleStr?: string
423		isSelected?: boolean
424		icon: TLUiMenuItemProps['icon']
425		onSelect: TLUiMenuItemProps['onSelect']
426		onDragStart: TLUiMenuItemProps['onDragStart']
427		overflow?: boolean
428	}) {
429		const events = useDraggableEvents(onDragStart, onSelect)
430	
431		if (overflow) {
432			return (
433				<TldrawUiToolbarButton
434					aria-label={labelStr}
435					aria-pressed={isSelected ? 'true' : 'false'}
436					isActive={isSelected}
437					className="tlui-button-grid__button"
438					data-testid={`tools.more.${id}`}
439					data-value={id}
440					disabled={disabled}
441					title={titleStr}
442					type="icon"
443					{...events}
444				>
445					<TldrawUiButtonIcon icon={icon!} />
446				</TldrawUiToolbarButton>
447			)
448		}
449	
450		return (
451			<TldrawUiToolbarButton
452				aria-label={labelStr}
453				aria-pressed={isSelected ? 'true' : 'false'}
454				data-testid={`tools.${id}`}
455				data-value={id}
456				disabled={disabled}
457				onTouchStart={(e) => {
458					preventDefault(e)
459					onSelect('toolbar')
460				}}
461				title={titleStr}
462				type="tool"
463				{...events}
464			>
465				<TldrawUiButtonIcon icon={icon!} />
466			</TldrawUiToolbarButton>
467		)
468	}
