1	import { preventDefault } from '@tldraw/editor'
2	import { ContextMenu as _ContextMenu, DropdownMenu as _DropdownMenu } from 'radix-ui'
3	import { unwrapLabel } from '../../../context/actions'
4	import { TLUiEventSource } from '../../../context/events'
5	import { useReadonly } from '../../../hooks/useReadonly'
6	import { TLUiTranslationKey } from '../../../hooks/useTranslation/TLUiTranslationKey'
7	import { useDirection, useTranslation } from '../../../hooks/useTranslation/useTranslation'
8	import { TldrawUiIcon, TLUiIconJsx } from '../TldrawUiIcon'
9	import { TldrawUiKbd } from '../TldrawUiKbd'
10	import { useTldrawUiMenuContext } from './TldrawUiMenuContext'
11	
12	/** @public */
13	export interface TLUiMenuCheckboxItemProps<
14		TranslationKey extends string = string,
15		IconType extends string = string,
16	> {
17		icon?: IconType | TLUiIconJsx
18		id: string
19		kbd?: string
20		title?: string
21		label?: TranslationKey | { [key: string]: TranslationKey }
22		lang?: string
23		readonlyOk?: boolean
24		onSelect(source: TLUiEventSource): Promise<void> | void
25		toggle?: boolean
26		checked?: boolean
27		disabled?: boolean
28	}
29	
30	/** @public @react */
31	export function TldrawUiMenuCheckboxItem<
32		TranslationKey extends string = string,
33		IconType extends string = string,
34	>({
35		id,
36		kbd,
37		label,
38		lang,
39		readonlyOk,
40		onSelect,
41		toggle = false,
42		disabled = false,
43		checked = false,
44	}: TLUiMenuCheckboxItemProps<TranslationKey, IconType>) {
45		const { type: menuType, sourceId } = useTldrawUiMenuContext()
46		const isReadonlyMode = useReadonly()
47		const msg = useTranslation()
48		const dir = useDirection()
49	
50		// If the editor is in readonly mode and the item is not marked as readonlyok, return null
51		if (isReadonlyMode && !readonlyOk) return null
52	
53		const labelToUse = unwrapLabel(label, menuType)
54		const labelStr = labelToUse ? msg(labelToUse as TLUiTranslationKey) : undefined
55	
56		switch (menuType) {
57			case 'menu': {
58				return (
59					<_DropdownMenu.CheckboxItem
60						dir={dir}
61						lang={lang}
62						className="tlui-button tlui-button__menu tlui-button__checkbox"
63						onSelect={(e) => {
64							onSelect?.(sourceId)
65							preventDefault(e)
66						}}
67						disabled={disabled}
68						checked={checked}
69					>
70						<TldrawUiIcon
71							small
72							label={msg(checked ? 'ui.checked' : 'ui.unchecked')}
73							icon={toggle ? (checked ? 'toggle-on' : 'toggle-off') : checked ? 'check' : 'none'}
74						/>
75						{labelStr && (
76							<span className="tlui-button__label" draggable={false}>
77								{labelStr}
78							</span>
79						)}
80						{kbd && <TldrawUiKbd>{kbd}</TldrawUiKbd>}
81					</_DropdownMenu.CheckboxItem>
82				)
83			}
84			case 'context-menu': {
85				return (
86					<_ContextMenu.CheckboxItem
87						key={id}
88						className="tlui-button tlui-button__menu tlui-button__checkbox"
89						dir={dir}
90						lang={lang}
91						onSelect={(e) => {
92							onSelect(sourceId)
93							preventDefault(e)
94						}}
95						disabled={disabled}
96						checked={checked}
97					>
98						<TldrawUiIcon
99							small
100							label={msg(checked ? 'ui.checked' : 'ui.unchecked')}
101							icon={toggle ? (checked ? 'toggle-on' : 'toggle-off') : checked ? 'check' : 'none'}
102						/>
103						{labelStr && (
104							<span className="tlui-button__label" draggable={false}>
105								{labelStr}
106							</span>
107						)}
108						{kbd && <TldrawUiKbd>{kbd}</TldrawUiKbd>}
109					</_ContextMenu.CheckboxItem>
110				)
111			}
112			default: {
113				// no checkbox items in actions menu
114				return null
115			}
116		}
117	}
